import { test, expect } from '@playwright/test';
import { MongoMemoryReplSet } from 'mongodb-memory-server';
import { createServer as createVite } from 'vite';
import { mkdtemp, rm, mkdir, writeFile } from 'node:fs/promises';
import { randomBytes } from 'node:crypto';
import os from 'node:os';
import { createHash } from 'node:crypto';
import path from 'node:path';
import { root } from '../../server/src/config.js';
import { connect, migrate, seed } from '../../server/src/persistence.js';
import { createApplication } from '../../server/src/app.js';
let repl, db, application, vite, folder;
const received=new Map();
test.beforeAll(async () => {
  folder = await mkdtemp(path.join(os.tmpdir(), 'dj-browser-assets-'));
  repl = await MongoMemoryReplSet.create({ replSet: { count: 1, storageEngine: 'wiredTiger' } });
  db = await connect(repl.getUri('browser_tests')); await migrate(db.connection, db.models); await seed(db.models);
  const wave = Buffer.alloc(1644);
  wave.write('RIFF'); wave.writeUInt32LE(1636,4); wave.write('WAVEfmt ',8); wave.writeUInt32LE(16,16);
  wave.writeUInt16LE(1,20); wave.writeUInt16LE(1,22); wave.writeUInt32LE(8000,24); wave.writeUInt32LE(16000,28);
  wave.writeUInt16LE(2,32); wave.writeUInt16LE(16,34); wave.write('data',36); wave.writeUInt32LE(1600,40);
  await writeFile(path.join(folder,'browser-fixture.wav'),wave);
  const asset = await db.models.Asset.create({ storageKey:'browser-fixture.wav', mimeType:'audio/wav', byteLength:wave.length, sha256:'test-fixture', licenseLabel:'Original HTTP test silence', sourceAttribution:'Generated for tests only' });
  await db.models.Track.create({ title:'Preview fixture',artist:'Test only',durationSeconds:0.1,assetId:asset._id,profileStatus:'pending',acoustic:null });
  const playable=Buffer.alloc(480044);wave.copy(playable,0,0,44);playable.writeUInt32LE(playable.length-8,4);playable.writeUInt32LE(playable.length-44,40);
  await writeFile(path.join(folder,'playback-fixture.wav'),playable);
  const playbackAsset=await db.models.Asset.create({storageKey:'playback-fixture.wav',mimeType:'audio/wav',byteLength:playable.length,sha256:createHash('sha256').update(playable).digest('hex'),licenseLabel:'Original test silence',sourceAttribution:'Generated only for playback tests'});
  await db.models.Track.updateMany({demoMetadataOnly:true},{$set:{assetId:playbackAsset._id,durationSeconds:30}});
  application = createApplication({ ...db, config: { key: randomBytes(48).toString('hex'), issuer: 'tests', audience: 'tests', origin: 'http://127.0.0.1:5173', secure: false, assetRoot: folder }, logger: { info() {}, error() {} } });
  const originalCommand=application.rooms.command.bind(application.rooms);
  application.rooms.command=async(...args)=>{const at=performance.timeOrigin+performance.now();const result=await originalCommand(...args);received.set(result.revision,at);return result;};
  await new Promise((resolve, reject) => { application.server.once('error', reject); application.server.listen(3000, '127.0.0.1', resolve); });
  vite = await createVite({ root: path.join(root, 'client'), configFile: path.join(root, 'client/vite.config.js') }); await vite.listen();
});
test.afterAll(async () => { await vite?.close(); await application?.close(); await db?.connection.close(); await repl?.stop(); if (folder) await rm(folder, { recursive: true, force: true }); });
test('two independent browser sessions create/join, sync and restore authentication', async ({ browser }) => {
  const hostContext = await browser.newContext(); const guestContext = await browser.newContext();
  const host = await hostContext.newPage(); const guest = await guestContext.newPage();
  const faults = []; host.on('pageerror', (e) => faults.push(e.message)); guest.on('pageerror', (e) => faults.push(e.message));
  const evidence = path.join(root, 'evidence'); await mkdir(evidence, { recursive: true });
  try {
    await host.goto('/'); await expect(host.getByRole('heading', { name: 'Good to have you back.' })).toBeVisible();
    await host.screenshot({ path: path.join(evidence, 'phase-three-welcome.png'), fullPage: true });
    async function register(page, name) {
      await page.goto('/'); await page.getByRole('button', { name: 'New here? Create an account' }).click();
      await page.getByLabel('Display name').fill(name); await page.getByLabel('Email address').fill(`${name.toLowerCase()}@example.test`); await page.getByLabel('Password', { exact: true }).fill('browser-test-password');
      await page.getByRole('button', { name: 'Create account →' }).click(); await expect(page.getByRole('heading', { name: 'Start a new lounge' })).toBeVisible();
    }
    await register(host, 'Host');
    await host.getByLabel('Search library').fill('Preview fixture');
    await expect(host.getByText('Test only · 0:00 · Profile needed')).toBeVisible();
    await host.getByRole('button', {name:'Preview',exact:true}).click();
    const audio = host.getByLabel('Preview Preview fixture');
    await expect(audio).toBeVisible();
    await expect.poll(() => audio.evaluate(a => a.readyState)).toBeGreaterThanOrEqual(2);
    await audio.evaluate(a => a.play());
    await expect.poll(() => audio.evaluate(a => a.ended)).toBe(true);
    await host.getByLabel('Search library').fill('');
    await host.getByLabel('Lounge vibe').fill('After Hours'); await host.getByLabel('Starting track').selectOption({ label: 'Study in Amber · 120 BPM' });
    await host.getByRole('button', { name: 'Create lounge →' }).click();
    await expect(host.getByText('Connected', { exact: true })).toBeVisible();
    const code = await host.locator('.invite-banner code').textContent();
    await register(guest, 'Guest'); await guest.getByLabel('Invite code').fill(code);
    const joinStarted=performance.now();await guest.getByRole('button', { name: 'Join lounge ↗' }).click();
    await expect(guest.getByText('Connected', { exact: true })).toBeVisible();
    const joinRenderMs=performance.now()-joinStarted;expect(joinRenderMs).toBeLessThan(2000);
    await expect(host.locator('.member')).toHaveCount(2); await expect(guest.locator('.member')).toHaveCount(2);
    await expect.poll(async()=>await host.locator('.sync-footer').textContent()===await guest.locator('.sync-footer').textContent()).toBe(true);
    await host.getByRole('button',{name:'Enable audio',exact:true}).click();
    await guest.getByRole('button',{name:'Enable audio',exact:true}).click();
    await host.getByRole('button',{name:'Play',exact:true}).click();
    await expect.poll(()=>host.getByLabel('Lounge audio').evaluate(a=>!a.paused&&a.currentTime>0)).toBe(true);
    await expect.poll(()=>guest.getByLabel('Lounge audio').evaluate(a=>!a.paused&&a.currentTime>0)).toBe(true);
    await host.getByRole('button',{name:'Pause',exact:true}).click();
    await expect.poll(()=>guest.getByLabel('Lounge audio').evaluate(a=>a.paused)).toBe(true);
    await host.getByLabel('Add a track').selectOption({label:'Night Geometry'});await host.getByRole('button',{name:'Add to queue',exact:true}).click();
    await expect(guest.locator('.queue-row')).toHaveCount(1);
    await host.getByLabel('Add a track').selectOption({label:'After the Rain'});await host.getByRole('button',{name:'Add to queue',exact:true}).click();
    await expect(guest.locator('.queue-row')).toHaveCount(2);
    for(const page of [host,guest])await page.evaluate(()=>{
      window.applied=[];
      const target=document.querySelector('.queue-panel');
      new MutationObserver(()=>window.applied.push({revision:Number(target.dataset.roomRevision),at:performance.timeOrigin+performance.now()})).observe(target,{attributes:true,attributeFilter:['data-room-revision']});
    });
    const latencies=[];
    for(let i=0;i<22;i++){
      await guest.getByRole('button',{name:'Upvote After the Rain',exact:true}).click();
      await expect(guest.getByRole('button',{name:'Upvote After the Rain',exact:true})).toHaveAttribute('aria-pressed',i%2===0?'true':'false');
      const rev=Number(await guest.locator('.queue-panel').getAttribute('data-room-revision'));
      await expect(host.locator('.queue-panel')).toHaveAttribute('data-room-revision',String(rev));
      const applied=await Promise.all([host,guest].map(page=>page.evaluate(rev=>window.applied.find(s=>s.revision===rev)?.at,rev)));
      if(i>=2)latencies.push(Math.max(...applied)-received.get(rev));
    }
    await guest.getByRole('button',{name:'Upvote After the Rain',exact:true}).click();
    await expect(host.locator('.queue-row').first()).toContainText('After the Rain');
    await expect(guest.locator('.queue-row').first()).toContainText('After the Rain');
    await host.getByRole('button',{name:'Suggest segue',exact:true}).click();
    await expect(guest.getByText(/template · pending/)).toBeVisible();
    await host.getByRole('button',{name:'Approve next track',exact:true}).click();
    await expect(guest.locator('.queue-row').filter({hasText:'Night Geometry'})).toContainText('Reserved next');
    await host.getByRole('button',{name:'Skip / Advance',exact:true}).click();
    await expect(guest.locator('.player h2')).toHaveText('Night Geometry');
    await host.getByRole('button',{name:'Pause',exact:true}).click();
    await guest.getByLabel('Ask about the current track').fill('What is the BPM tempo?');
    await guest.getByRole('button',{name:'Ask AI DJ',exact:true}).click();
    await expect(guest.getByText('BPM tempo: 124.',{exact:true}).first()).toBeVisible();
    await guest.getByLabel('Ask about the current track').fill('Who won a Nobel prize?');
    await guest.getByRole('button',{name:'Ask AI DJ',exact:true}).click();
    await expect(guest.getByText('Insufficient authored metadata to answer this question.',{exact:true})).toBeVisible();
    const sorted=[...latencies].sort((a,b)=>a-b);
    await writeFile(path.join(evidence,'phase-three-browser-latency.json'),JSON.stringify({date:'2026-10-26',node:process.version,platform:process.platform,cpu:os.cpus()[0].model,memoryGiB:Math.round(os.totalmem()/1024**3),joinRenderMs,workload:'Two Chromium contexts; 2 warmup and 20 sequential votes; real local MongoDB replica set; command receipt to last client DOM revision apply',samplesMs:latencies,p50:sorted[9],p95:sorted[18],p99:sorted[19],max:sorted[19],limits:'Local smoke workload, not a 50-user or 10-minute performance certification'},null,2));
    expect(Math.max(...latencies)).toBeLessThan(100);
    await host.screenshot({ path: path.join(evidence, 'phase-three-lounge.png'), fullPage: true });
    await guest.reload(); await expect(guest.getByRole('heading', { name: 'Start a new lounge' })).toBeVisible();
    await guest.getByRole('button', { name: /After Hours .* ↗/ }).click(); await expect(guest.getByText('Connected', { exact: true })).toBeVisible();
    await guest.setViewportSize({ width: 390, height: 844 });
    await guest.getByLabel('Ask about the current track').fill('What is the BPM tempo?');
    await guest.getByRole('button',{name:'Ask AI DJ',exact:true}).click();
    await expect(guest.getByText('BPM tempo: 124.',{exact:true}).first()).toBeVisible();
    await guest.locator('.citations summary').first().click();
    await guest.screenshot({ path: path.join(evidence, 'phase-three-mobile.png'), fullPage: true });
    expect(await guest.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth)).toBe(true);
    await host.getByRole('button',{name:'Overview',exact:false}).click();
    await expect(guest.getByText('Host disconnected. Playback and queue changes are frozen.',{exact:true})).toBeVisible();
    await guest.getByRole('button', { name: 'Sign out' }).click(); await expect(guest.getByRole('heading', { name: 'Good to have you back.' })).toBeVisible();
    expect(faults).toEqual([]);
  } finally { await hostContext.close(); await guestContext.close(); }
});
